// === Tab: Shader ===
//https://www.color-hex.com/color-palette/24334

function getShader(_renderer) {
	const vert = `
		// our vertex data
		attribute vec3 aPosition;

		// our texcoordinates
		attribute vec2 aTexCoord;

		// this is a variable that will be shared with the fragment shader
		// we will assign the attribute texcoords to the varying texcoords to move them from the vert shader to the frag shader
		// it can be called whatever you want but often people prefiv it with 'v' to indicate that it is a varying
		varying vec2 vTexCoord;

		void main() {

			// copy the texture coordinates
			vTexCoord = aTexCoord;

			// copy the position data into a vec4, using 1.0 as the w component
			vec4 positionVec4 = vec4(aPosition, 1.0);
			positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

			// send the vertex information on to the fragment shader
			gl_Position = positionVec4;
		}
	`;

	const frag = `
precision mediump float;
varying vec2 vTexCoord;
uniform float noiseSeed;
uniform vec2 coords;

float map(float value, float min1, float max1, float min2, float max2) {
  return min2 + (value - min1) * (max2 - min2) / (max1 - min1);
}

float rand(vec2 n) { 
	return fract(sin(dot(n, vec2(12.9898, 4.1414))) * noiseSeed);
}

float noise(vec2 p){
	vec2 ip = floor(p);
	vec2 u = fract(p);
	u = u*u*(3.0-2.0*u);

	float res = mix(
		mix(rand(ip),rand(ip+vec2(1.0,0.0)),u.x),
		mix(rand(ip+vec2(0.0,1.0)),rand(ip+vec2(1.0,1.0)),u.x),u.y);
	return res*res;
}

void main() {
	vec2 coord = vTexCoord;
	coord += coords;
	float a = 0.6*noise(coord*2.0)+0.1*noise(coord*4.0)+0.17*noise(coord*6.0)+0.1*noise(coord*7.0)+0.02*noise(coord*200.0)+0.01*noise(coord*100.0);
	vec3 col = vec3(0.0, 0.0, 0.0);
	if(a<0.25) {
		col.x = map(a, 0.0, 0.25, 0.0, 68.0);
		col.y = map(a, 0.0, 0.25, 7.0, 0.0);
		col.z = map(a, 0.0, 0.25, 111.0, 139.0);
	}
	else if(a<0.5) {
		col.x = map(a, 0.25, 0.5, 68.0, 159.0);
		col.y = map(a, 0.25, 0.5, 0.0, 69.0);
		col.z = map(a, 0.25, 0.5, 139.0, 176.0);
	}
	else if(a<0.75) {
		col.x = map(a, 0.5, 0.75, 159.0, 229.0);
		col.y = map(a, 0.5, 0.75, 69.0, 78.0);
		col.z = map(a, 0.5, 0.75, 176.0, 208.0);
	}
	else {
		col.x = map(a, 0.75, 1.0, 229.0, 255.0);
		col.y = map(a, 0.75, 1.0, 78.0, 228.0);
		col.z = map(a, 0.75, 1.0, 208.0, 242.0);
	}
	col /= 255.0;

  gl_FragColor = vec4(col, 1.0);
}
	`;

	return createShader(vert, frag);
}

